import java.util.*;

class SummaryRanges {
  private final TreeMap<Integer, Integer> intervals = new TreeMap<>(); // start -> end

  public SummaryRanges() {}

  public void addNum(int value) {
    Map.Entry<Integer, Integer> lower = intervals.floorEntry(value);
    if (lower != null && lower.getValue() >= value) return;
    int start = value, end = value;
    if (lower != null && lower.getValue() == value - 1) {
      start = lower.getKey();
      intervals.remove(start);
    }
    Integer higher = intervals.ceilingKey(value + 1);
    if (higher != null && higher == value + 1) end = intervals.remove(higher);
    intervals.put(start, end);
  }

  public int[][] getIntervals() {
    int[][] res = new int[intervals.size()][];
    int i = 0;
    for (Map.Entry<Integer, Integer> e : intervals.entrySet()) res[i++] = new int[] {e.getKey(), e.getValue()};
    return res;
  }
}
